// Decision ledger (POC): reads docs/decisions/ at build time. Records are written
// by scripts/decisions/decide.ts; precedents.yaml is generated by extract-precedents.ts.
import { existsSync, readdirSync, readFileSync } from "node:fs";
import { join } from "node:path";
import { parse } from "yaml";
import { repoPath } from "./paths";

export interface DecisionRecord {
  id: string;
  date?: string;
  lane?: string;
  class?: string;
  question?: string;
  options?: string[];
  status?: string;
  step?: string;
  decision?: string;
  confidence?: number | string;
  reversible?: boolean;
  rationale?: string;
  precedent?: { id?: string; source_file?: string; score?: number };
  needs_precedent?: boolean;
  review_sampled?: boolean;
  decided_by?: { agent?: string; pipeline?: string };
}

const RECORDS_DIR = () => repoPath("docs", "decisions", "records");

export function decisionRecords(): DecisionRecord[] {
  const dir = RECORDS_DIR();
  if (!existsSync(dir)) return [];
  return readdirSync(dir)
    .filter((f) => f.endsWith(".yaml"))
    .sort()
    .map((f) => {
      const abs = join(dir, f);
      try {
        return parse(readFileSync(abs, "utf8")) as DecisionRecord;
      } catch (e) {
        // Loud failure with the file named — a corrupt record (e.g. an unresolved
        // merge) must break the build visibly, never silently drop off the ledger.
        throw new Error(`decision record ${abs} failed to parse: ${(e as Error).message}`);
      }
    });
}

export function precedentCount(): number {
  const f = repoPath("docs", "decisions", "precedents.yaml");
  if (!existsSync(f)) return 0;
  const doc = parse(readFileSync(f, "utf8")) as { precedents?: unknown[] };
  return doc.precedents?.length ?? 0;
}

export function decisionStats(records: DecisionRecord[]) {
  const byStatus: Record<string, number> = {};
  for (const r of records) byStatus[r.status ?? "unknown"] = (byStatus[r.status ?? "unknown"] ?? 0) + 1;
  return { total: records.length, byStatus, precedents: precedentCount() };
}
